573: 
574:   _buildContactShadow() {
575:     const c = document.createElement('canvas');
576:     c.width = c.height = 128;
577:     const ctx = c.getContext('2d');
578:     const grad = ctx.createRadialGradient(64, 64, 3, 64, 64, 62);
579:     grad.addColorStop(0, 'rgba(0,0,0,0.68)');
580:     grad.addColorStop(0.5, 'rgba(0,0,0,0.34)');
581:     grad.addColorStop(1, 'rgba(0,0,0,0)');
582:     ctx.fillStyle = grad;
583:     ctx.fillRect(0, 0, 128, 128);
584:     const tex = new THREE.CanvasTexture(c);
585:     tex.colorSpace = THREE.SRGBColorSpace;
586: 
587:     const geo = new THREE.PlaneGeometry(1.7, 2.55);
588:     geo.rotateX(-Math.PI / 2);
589:     const material = new THREE.MeshBasicMaterial({
590:       map: tex, transparent: true, depthWrite: false, opacity: 0.7, toneMapped: false,
591:     });
592:     this.contactShadow = new THREE.Mesh(geo, material);
593:     this.contactShadow.renderOrder = 2;
594:     this.contactShadow.visible = false;
595:     this.scene.add(this.contactShadow);
596:   }
