613:   reset(x, y, z, heading) {
614:     this.group.position.set(x, y, z);
615:     this.group.rotation.set(0, heading, 0);
616:     this.tilt.rotation.set(0, 0, 0);
617:     this.clearTrick();
618:     this.body.rotation.set(0, 0, 0);
619:     this.body.position.y = 0;
620:     this.head.rotation.set(0, 0, 0);
621:     this.legs.forEach(l => {
622:       l.hip.position.y = 0.96;
623:       l.upper.group.rotation.x = -0.12;
624:       l.lower.group.rotation.x = 0.28;
625:       l.ankle.rotation.x = 0;
626:     });
627:     this.arms.forEach(a => {
628:       a.shoulder.rotation.set(0, 0, a.side * 0.15);
629:       a.upper.group.rotation.set(0, 0, a.side * 0.15);
630:       a.elbow.rotation.x = 0.18;
631:     });
632:   }
633: 
634:   update(dt, s) {
635:     const g = this.group;
636:     g.position.set(s.x, s.y, s.z);
637:     g.rotation.y = s.heading;
638: 
639:     // soft contact shadow that tightens near the ground and fades in the air
640:     const gy = s.groundY;
641:     if (Number.isFinite(gy)) {
642:       const height = Math.max(0, (s.y ?? gy) - gy);
643:       const fade = Math.max(0, 1 - height / 4.5);
644:       const shadow = this.contactShadow;
645:       shadow.visible = fade > 0.03;
646:       shadow.position.set(s.x, gy + 0.018, s.z);
647:       shadow.rotation.y = s.heading;
648:       const spread = 1 + height * 0.16;
649:       shadow.scale.set(spread, 1, spread);
650:       shadow.material.opacity = 0.68 * fade * fade + 0.12 * fade;
651:     } else {
652:       this.contactShadow.visible = false;
653:     }
654: 
655:     const speed = Math.abs(s.speed || 0);
656:     const air = s.air || 0;
657:     const crouch = s.crouch || 0;
658:     const lean = s.lean || 0;
659:     const grind = s.grinding ? 1 : 0;
660:     const manual = s.manual ? 1 : 0;
661:     const grab = s.grab ? 1 : 0;
662:     const bail = s.bail || 0;
663:     const charging = s.charging ? 1 : 0;
664: 
665:     this.bob += dt * (2 + speed * 0.55);
666:     this.pushPhase += dt * (3.2 + speed * 0.8);
667: 
668:     // overall tilt: slope pitch, carving lean, grind balance
669:     const slopePitch = s.slopePitch || 0;
670:     const bal = s.balance || 0;
671:     if (bail > 0) {
672:       const t = s.bailTime || 0;
673:       this.tilt.rotation.x += (Math.sin(t * 10) * 0.35 - this.tilt.rotation.x) * Math.min(1, dt * 12);
674:       this.tilt.rotation.z += (Math.cos(t * 8) * 0.4 - this.tilt.rotation.z) * Math.min(1, dt * 12);
675:       this.tilt.rotation.y = Math.sin(t * 7) * 0.4;
676:     } else {
677:       this.tilt.rotation.x += (-slopePitch * 0.85 - this.tilt.rotation.x) * Math.min(1, dt * 10);
678:       this.tilt.rotation.z += (-lean * 0.17 + bal * 0.16 - this.tilt.rotation.z) * Math.min(1, dt * 9);
679:       this.tilt.rotation.y += (0 - this.tilt.rotation.y) * Math.min(1, dt * 9);
680:     }
681: 
682:     // body crouch + air pose
683:     const bodyBase = 0.96 - crouch * 0.16 - charging * 0.06 - (manual ? 0.02 : 0);
684:     const swing = Math.sin(this.bob) * 0.015 * Math.min(1, speed / 4);
685:     this.body.position.y = swing - air * 0.03;
686: 
687:     for (const leg of this.legs) {
688:       const back = leg.side > 0 ? 1 : -1;
689:       const stance = back * 0.16;
690:       leg.hip.position.y = bodyBase;
691:       leg.hip.position.z = leg.side * 0.235 + (manual ? 0.035 : 0);
692:       let upperX = -0.18 + crouch * 0.62 + air * 0.55 + (grab ? 0.35 : 0) + stance * 0.5;
693:       let lowerX = 0.34 + crouch * 0.82 + air * 0.85 + (grab ? 0.6 : 0) - stance * 0.2;
694:       if (grind) { upperX += 0.08; lowerX += 0.25; }
695:       if (manual) { upperX += -0.12; lowerX -= 0.2; }
696:       leg.upper.group.rotation.x += (upperX - leg.upper.group.rotation.x) * Math.min(1, dt * 14);
697:       leg.lower.group.rotation.x += (lowerX - leg.lower.group.rotation.x) * Math.min(1, dt * 14);
698:       leg.hip.rotation.z = leg.side * (0.04 + crouch * 0.07);
699:       leg.knee.rotation.z = leg.side * 0.04;
