  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(w * 0.8, h * 0.72),
    new THREE.MeshStandardMaterial({ map: graffiti, transparent: true, roughness: 0.9 })
  );
  panel.position.set(x, h * 0.5, z + d / 2 + 0.01);
