  const edge = new THREE.Mesh(new THREE.BoxGeometry(w, 0.055, d + 0.08), metal);
  edge.position.set(x, h + 0.01, z);
  edge.rotation.y = rot;
  group.add(edge);
  scene.add(group);

  return { x, z, w, d, h, rot };
}

