+function bendDeckGeometry(geo, halfWidth, halfLength, rise = 0.095, concave = 0.011) {
+  const pos = geo.attributes.position;
+  for (let i = 0; i < pos.count; i++) {
+    const x = pos.getX(i);
+    const z = pos.getZ(i);
+    const t = Math.max(0, (Math.abs(z) - halfLength * 0.53) / (halfLength * 0.47));
