+    const bowl = -Math.pow(Math.min(1, Math.abs(x) / halfWidth), 2) * concave;
+    pos.setY(i, pos.getY(i) + kick + bowl);
+  }
+  pos.needsUpdate = true;
+  geo.computeVertexNormals();
+  return geo;
